for idx, (roff, coff) in enumerate(demo_cell_offsets):
    # Extract 2x2 cell content properly
    rows = demo_input[roff:roff+2]
    cols = []
    for row in rows:
        cols.append(row[coff:coff+2])

    five_positions = []
    for r in range(2):
        for c in range(2):
            if cols[r][c] == 5:
                five_positions.append((r,c))

    print(f"Demo Cell {idx} ({idx//3},{idx%3}):")
    print(f"  Positions of 5: {five_positions}")

    # Check pairwise alignments
    aligned = False
    alignment_types = set()
    if len(five_positions) >= 2:
        for i in range(len(five_positions)):
            for j in range(i+1, len(five_positions)):
                r1, c1 = five_positions[i]
                r2, c2 = five_positions[j]

                same_row = r1 == r2
                same_col = c1 == c2

                diag_main = abs(r1-r2) == abs(c1-c2) and (r2 > r1) == (c2 < c1)  # \ direction
                diag_anti = abs(r1-r2) == abs(c1-c2) and (r2 > r1) == (c2 > c1)  # / direction

